use strict;
use warnings;
use utf8;
use Scalar::Util qw(blessed refaddr);
use JSON::PP;
use Config;
use LeanBridge::Recursive;
use LeanBridge::Linked;
use LeanBridge::Deep;
use LeanBridge::Builtins;
my $checks=0;
sub check { ++$checks; die "check $checks failed\n" unless $_[0] }
sub rejects (&) {my ($call)=@_;my $ok=eval {$call->();1};check(!$ok && length($@));}
my $leaf=LeanBridge::Recursive::Spine::Leaf->new(value=>7);
my $next=LeanBridge::Recursive::Spine::Next->new(value=>$leaf);
check($next->value->value==7);
check(blessed($next) eq 'LeanBridge::Recursive::Spine::Next');
check($next->isa('LeanBridge::Recursive::Spine'));
check(refaddr($next->value)==refaddr($leaf));
$leaf->{value}=9;check($next->value->value==9);
rejects {LeanBridge::Recursive::Spine->new()};
rejects {LeanBridge::Recursive::Spine::Leaf->new()};
rejects {LeanBridge::Recursive::Spine::Leaf->new(value=>1,extra=>2)};
rejects {LeanBridge::Recursive::Spine::Leaf->new(value=>1,value=>2)};
rejects {LeanBridge::Recursive::Spine::Leaf->new(value=>1,'unpaired')};
rejects {LeanBridge::Recursive::Spine::Leaf->new([]=>1)};
rejects {LeanBridge::Recursive::Spine::Leaf->new(undef=>1)};
my $none=LeanBridge::Recursive::Some->new(undef);
my $nested=LeanBridge::Recursive::Some->new($none);
check(!defined($none->value));check(refaddr($nested->value)==refaddr($none));
rejects {LeanBridge::Recursive::Some->new()};
rejects {LeanBridge::Recursive::Some->new(undef,undef)};
my $ok=LeanBridge::Recursive::Ok->new(7),my $err=LeanBridge::Recursive::Err->new(7);
check(blessed($ok) ne blessed($err));check($ok->value==$err->value);
my $left=LeanBridge::Recursive::LeftTree::Leaf->new(value=>4);
my $right=LeanBridge::Recursive::RightTree::Many->new(lefts=>[$left]);
check(LeanBridge::Recursive::LeftTree::Next->new(right=>$right)->right->lefts->[0]->value==4);
my %values=(unit=>undef,bool=>LeanBridge::Recursive::true(),u8=>255,u16=>65535,u32=>4294967295,u64=>18446744073709551615,
 i8=>-128,i16=>-32768,i32=>-2147483648,i64=>-9223372036854775808,natural=>Math::BigInt->new(2)->bpow(1001),
 integer=>Math::BigInt->new(-42),f32=>1.5,f64=>-2.5,text=>"λ\0🌿",bytes=>pack('C*',0,255),char=>'🌿',word=>7,signedWord=>-7);
my $scalars=LeanBridge::Recursive::Scalars->new(%values);
for my $name (keys %values) {check(exists($scalars->{$name}));check($scalars->can($name));}
check($scalars->natural->bcmp($values{natural})==0);check($scalars->char eq '🌿');
my $replacement=LeanBridge::Recursive::Scalars->new(%values,text=>'changed');check($replacement->text eq 'changed');
my $tree=LeanBridge::Recursive::Tree::Leaf->new(payload=>$scalars);
my $branch=LeanBridge::Recursive::Tree::Branch->new(children=>[$tree,$tree]);
check(refaddr($branch->children->[0])==refaddr($branch->children->[1]));
my $envelope=LeanBridge::Recursive::Envelope->new(tree=>$tree,alternatives=>[[$tree],[]],fallback=>$none,outcome=>$ok,marker=>$nested);
check($envelope->tree->payload->text eq $values{text});
check(blessed(LeanBridge::Recursive::EmptyRecord->new()) eq 'LeanBridge::Recursive::EmptyRecord');
check(blessed(LeanBridge::Recursive::Marker::Empty->new()) ne blessed(LeanBridge::Recursive::Marker::Unit->new(value=>undef)));
my %wide=map {("field$_"=>$_)} 0..254;
my $wide=LeanBridge::Recursive::Wide::Next->new(%wide,child=>LeanBridge::Recursive::Wide::Leaf->new(value=>42));
check($wide->field254==254);check($wide->child->value==42);
check(!LeanBridge::Recursive::Forest->can('new'));
check(!LeanBridge::Recursive::TreeAlias->can('new'));
check(!LeanBridge::Recursive->can('spine'));
my $tail=LeanBridge::Linked::Link->new(tail=>undef,value=>9);
my $head=LeanBridge::Linked::Link->new(tail=>LeanBridge::Linked::Some->new($tail),value=>7);
check($head->tail->value->value==9);check(!defined($tail->tail));
check(refaddr($head->tail->value)==refaddr($tail));
rejects {LeanBridge::Linked::Link->new(value=>4)};
rejects {LeanBridge::Linked::Link->new(tail=>undef,value=>4,extra=>0)};
$tail->{value}=12;check($head->tail->value->value==12);
check(!LeanBridge::Deep::Alias699->can('new'));check(!LeanBridge::Deep::Alias0->can('new'));
my $vacant='LeanBridge::Recursive::Never';
check($vacant->can('new'));
rejects {$vacant->new()};
my $leaf_again=LeanBridge::Recursive::Spine::Leaf->new(value=>7);
check(refaddr($leaf_again)!=refaddr($leaf));
rejects {LeanBridge::Recursive::EmptyRecord->new(extra=>0)};
rejects {LeanBridge::Recursive::Marker::Empty->new(value=>undef)};
rejects {LeanBridge::Recursive::Marker::Unit->new()};
my @builtins=qw(keys ref bless die shift splice exists defined grep length push map);
my %builtins=map {($_=>42)} @builtins;
my $builtin=LeanBridge::Builtins::Link->new(tail=>undef,value=>7,%builtins);
for my $name (@builtins) {check($builtin->$name()==42);}
rejects {$builtin->new(tail=>undef,value=>7,%builtins)};
rejects {$none->new(undef)};
rejects {$leaf->new(value=>7)};
rejects {LeanBridge::Recursive::Some->new(undef,extra=>1)};
rejects {LeanBridge::Recursive::Ok->new()};
rejects {LeanBridge::Recursive::Err->new()};
check(LeanBridge::Recursive::true());check(!LeanBridge::Recursive::false());
print JSON::PP->new->canonical->encode({checks=>$checks,perl=>sprintf('%vd',$^V),threaded=>($Config{useithreads}//'') eq 'define'?JSON::PP::true:JSON::PP::false,wordBits=>8*$Config{ivsize},pointerBits=>8*$Config{ptrsize}}),"\n";
